use opencodex_desktop_lib::modules::{update::release_notes::{self,Channel,Target,Request,HttpSource,Source},runtime_defaults,preferences::ProxyPolicy};
use std::{path::PathBuf,time::{Instant,SystemTime,UNIX_EPOCH}};
fn main(){let root=PathBuf::from(std::env::args().nth(1).expect("explicit scratch root"));assert!(root.starts_with("/private/tmp/ocxd-diagnostic-final-20261110"));std::fs::create_dir_all(&root).unwrap();let rt=tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap();let result=rt.block_on(async{let source=HttpSource::new(ProxyPolicy::None,runtime_defaults::release_notes()).unwrap();let mut steps=Vec::new();for (name,url) in [("npm","https://registry.npmjs.org/@bitkyc08%2fopencodex/2.99.0"),("github-api","https://api.github.com/repos/lidge-jun/opencodex/releases/tags/v2.99.0")]{let start=Instant::now();let r=source.get(url).await;steps.push(serde_json::json!({"target":name,"result":match &r{Ok(Some(_))=>"received",Ok(None)=>"404",Err(_)=>"error"},"error":r.as_ref().err().map(|e|format!("{e:?}")),"bytes":r.as_ref().ok().and_then(|b|b.as_ref()).map(|b|b.len()),"elapsedMs":start.elapsed().as_millis()}));}let start=Instant::now();let queried=release_notes::query(&source,&root,Request{target:Target::Official,channel:Channel::Official,version:"2.99.0",updater_notes:None,force:true,now:SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs() as i64},runtime_defaults::release_notes()).await;serde_json::json!({"scope":"Actual Desktop production HttpSource and release_notes::query, direct mode, isolated cache; no GUI command preadmission or install","steps":steps,"query":match queried{Ok(d)=>serde_json::json!({"notesState":format!("{:?}",d.notes_state),"notesPresent":d.notes.is_some(),"notesSource":d.notes_source,"candidateVersion":d.candidate_version,"cacheHit":d.cached}),Err(e)=>serde_json::json!({"error":format!("{e:?}")})},"queryMs":start.elapsed().as_millis()})});println!("{}",serde_json::to_string_pretty(&result).unwrap());}
